code_examples.code:
.container {
  display: flex;
  gap: 10px;
}
.container p {
  width: 100px;   /* used only if no flex-basis */
}

.item {
  width: 100px;        /* ignored */
  flex-basis: 200px;   /* starting size */
  max-width: 150px;    /* final size cannot exceed this */
  min-width: 50px;     /* cannot shrink below this */
}

.item {
  flex-grow: 1;
  flex-shrink: 1;
  flex-basis: 0;
}
/* same as */
.item { flex: 1 1 0; }
/* same as */
.item { flex: 1; }

